    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// Find method for <t>METALMSupplierVolumetricRebateLine</t>
    /// </summary>
    /// <param name = "_number">METALMSupplierVolumetricRebate Number</param>
    /// <param name = "_lineNumber">Line number</param>
    /// <param name = "_forupdate">boolean forUpdate</param>
    /// <returns>A METALMSupplierVolumetricRebateLine if found, otherwise null</returns>
    static METALMSupplierVolumetricRebateLine find(
                METALMSupplierVolumetricRebateNumber _number,
                LineNum _lineNumber,
                boolean _forupdate = false)
    {
        METALMSupplierVolumetricRebateLine line;

        if (_lineNumber && _number != '')
        {
            line.selectForUpdate(_forupdate);

            select firstonly line
                where   line.ALMSupplierVolumetricRebateNumber == _number
                &&  line.LineNumber == _lineNumber;
        }
        
        return line;
    }

    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// FindRecId method for <t>METALMSupplierVolumetricRebateLine</t>
    /// </summary>
    /// <param name = "_recId">RecId</param>
    /// <param name = "_forupdate">boolean forUpdate</param>
    /// <returns>A METALMSupplierVolumetricRebateLine if found, otherwise null</returns>
    static METALMSupplierVolumetricRebateLine findRecId(
                        RecId _recId,
                        boolean _forupdate = false)
    {
        METALMSupplierVolumetricRebateLine line;

        if (_recId)
        {
            line.selectForUpdate(_forupdate);

            select firstonly line
                where line.RecId == _recId;
        }
        
        return line;
    }

    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// Exist method for <t>METALMSupplierVolumetricRebateLine</t>
    /// </summary>
    /// <param name = "_number">ALMSupplierVolumetricRebate Number</param>
    /// <param name = "_lineNumber">Line number</param>
    /// <returns>true is record is found, false otherwise</returns>
    static boolean exist(METALMSupplierVolumetricRebateNumber _number,
                        LineNum _lineNumber)
    {
        boolean found;

        found = (select firstonly RecId from
            METALMSupplierVolumetricRebateLine
            where
            METALMSupplierVolumetricRebateLine.ALMSupplierVolumetricRebateNumber == _number
            && METALMSupplierVolumetricRebateLine.LineNumber == _lineNumber)
            .RecId != 0;
         
        return found;
    }

    /// <summary>
    /// MPJ-5904, GVivanco, 26Jun2021
    /// Calculates the value of the last LineNumber inserted for a
    /// ALMSupplierVolumetricRebate
    /// </summary>
    /// <param name = "_number">ALMSupplierVolumetricRebate Number</param>
    /// <returns>last Line number</returns>
    public static LineNum lastLineNumber(METALMSupplierVolumetricRebateNumber _number)
    {
        METALMSupplierVolumetricRebateLine line;

        if (_number)
        {
            select maxof(LineNumber) from line
                where line.ALMSupplierVolumetricRebateNumber == _number;
        }

        return line.LineNumber;
    }

/// <summary>
